float sdWireBox(vec3 p, float s, float b) {
    float d = 0.;
    float o = s + .5;
    float i = s - b;
    float k = .1;
    d = smax(
        -box(p, vec3(o, i, i)),
        box(p, vec3(s)), k
    );
    d = smax(
        -box(p, vec3(i, o, i)),
		d,k
    );
    d = smax(
        -box(p, vec3(i, i, o))-.1,
		d, k
    );

    return d;
}


