vec2 g_fid, g_fp;
float map(vec3 p) {   

    g_p = p;
    for(float i = 0.; i < 3.; i++) {
        p.x = abs(p.x) -5.5;
        p.xz *= rot(PI/5.);
    }

    vec3 bp1 = p;

   // p.x = pMod(p.x, 4.9);



   // cam(p);
    p.z -= 5.;
    pModPolar(p.xz, 16.);


         //   p.yz *= mix(.8, 1.5, S(0., 20., p.y));

    p.x -= 19.;//-mix(0., 10., smoothstep(0., 20., p.y));
    p.xz *= rot(.5*PI);

    vec3 bp0 = p;
    pModInterval1(p.y, 7.2, 0., 2.);

    vec3 bp = p; 
    float d = 1e9;


    float sx = sabsk(p.x, .5);

    p.z += .1*sin(2.5*sx+.8*abs(p.y));
    d = box(p, vec3(4, 3.4, 0.4))-0.04;

    p.y -= .3;

    float w =  mix(0., 1., smoothstep(-2., -.5, -p.y)+.4*SIN(5.5* max(.6, p.y)));


    float dw = box(p, vec3(vec2(w, PHI)*1.2, 1.));
    p = bp;
    //d = max(d, -dw);

    d = opDifferenceColumns(d, dw, .12, 3.);


    p.z += 2.5;
    vec3 pf = p;
    pf.y = abs(p.y) - 3.6;

    w = 4.;

    pf.z += .2*sin(.5*sx*p.y*w/(2.*PI))*smoothstep(.22, -2., p.y);

    pf.y += .05*sin(.9*sx*p.y*w/(2.*PI))*smoothstep(.22, -2., p.y);

    float fl = box(pf, vec3(w, .5, 3.))-.01;

    p.y -= 2.9;
    p.z += 3.;
    p.y *= 4.5;
    fl = smax(fl, -(length(p) - 3.), .5)*.5;


    p = bp0;
    p.z += 6. + .2*sin(.5*sx*p.y*w/(2.*PI))*smoothstep(.22, -2., p.y);
    p.y += 4.5;
    float stairs = box(p, vec3(w, .5, 2.))-0.01;
    fl = opUnionStairs(fl, stairs, .9, 3.);
    d = min(fl, d);


    p = bp;
    p.x = abs(p.x)-2.1;


    p.z += 3.4;
    w = mix(0.3, .5, .5+.5*cos(p.y-.5)) + .1*SIN(11.*sabsk(p.x, .4)*sabsk(p.y, .5)-.8*tt);

      //  p.xz *= rot(1.4*p.y);
   // p.xz -= .1*sin(4.*p.y);

    float c = sdCylinder(p, w, 3.);

    p.y = abs(p.y) - 3.;
    float c1 = sdCylinder(p, .54, .2);

    c = opUnionColumns(c, c1, .5, 4.);
    d = min(c, d);

    p = bp1;
    p.y -= 18.;
    float dome = max(-p.y, abs(length(p) - 19.)-.4);

    g_mat = dome < d ? 1. : 0.;

    d = min(d, dome);

    p = bp1;

   // p.xz *= rot(PI/8.);
    g_fid = pMod(p.xz, vec2(.8));

    p.y += 5.;

    g_fp = p.xz;
    fl = box(p, vec3(.34))-.09;

    g_mat = fl < d ? 2. : g_mat;
    d = min(d, fl);

    return d*.5;

}


vec3 getNormal(vec3 p) {

    vec2 eps = vec2(0.001, 0.0);
    return normalize(vec3(map(p + eps.xyy) - map(p - eps.xyy),
                          map(p + eps.yxy) - map(p - eps.yxy),
                          map(p + eps.yyx) - map(p - eps.yyx)
                         )
                     );
}

float stars(vec2 p) {

    float N = 20.;
    vec2 id = floor(p*N)-.5;
    p = fract(p*N)-.5;

    float s = noise(id*20.+ 4.);
    float v = float(noise(id*30.+6.) < .4);


    p.xy += vec2(noise(id*30.+ 1.), noise(id*20.+ 3.))*.3-.4;

    return 2.*(1.-pow(smoothstep(.0, .1*s, (length(p))), 3.))*v;
}

// iq's shadow function
float softshadow( in vec3 ro, in vec3 rd, float mint, float maxt, float k ) {

    float res = 1.0;
    float ph = 1e20;
    for( float t=mint; t<maxt; )
    {
        float h = map(ro + rd*t);
        if( h<0.001 )
            return 0.0;
        float y = h*h/(2.0*ph);
        float d = sqrt(h*h-y*y);
        res = min( res, k*d/max(0.0,t-y) );
        ph = h;
        t += h;
    }
    return res;
}


// rainbow gradient palette
vec3 palette(float x) {
    return 0.5 +.5 * cos(vec3(1)*x*2.*PI + vec3(0, 5., 4));
}

// signed distance to a circle
float circle(vec2 p, float r) {
    return length(p) - r;
}

// signed distance to a rectangle
float rect(vec2 p, vec2 s) {
    p = abs(p);
    return max(p.x - s.x, p.y - s.y);
}


// pattern distance function
float pattern(vec2 p) {

    // polar transform
    p = toPolar(p);

    // number of repetions
    float N = 8.;

    // repeat along the radial axis (polar angle)
    p.y = fract(N*p.y/(2.*PI)) - .5;

    // mirror/symmetry, "pushed" together sligtly
    p.y = abs(p.y) + .1;

    // convert back to acrtesian
    p = fromPolar(p);

    // repeat pattern in x and y (tiling), center origin
    p = fract(p*6.) - .5;

    // mirror
    p = abs(p) - .1;

    // KIFS function rotation and mirror in each step
    for(float i=0.; i < 4.; i++) {        
        p *= rot(PI/9. + .05*iTime);
       // p.x += sin(p.y*.1 + i)*.1;
        p = abs(p) - .3;
    }

    // save coordinate state to reuse later (bp = "base pointer") 
    vec2 bp = p;
    float d = 1e9;

    // offset first cirlce to the left
    p.x -= .2;
    float c = circle(p, .3);

    // circle outline
    c = abs(c) - .02;

    // reset coordinate to saved state
    p = bp;

    // offset second cirlce to the right
    p.x += .2;
    float c2 = circle(p, .3);

    // circle outline
    c2 = abs(c2) - .02;

    // combine first and second circle
    c = min(c, c2);
    p = bp; 

    // horizontal symmetry for the square
    p.x = abs(p.x)-.35;
    p *= rot(.25*PI);

    float s = rect(p, vec2(.18));

    // outline of the square
    s = abs(s) - .02;  

    // combine circles and squares
    d = min(s, c);

    return d;

}

// texture from my rug tutorial
// https://www.shadertoy.com/view/lXcfWB
vec3 mandalaTexture(vec2 uv, float off) {

    // Time varying pixel color
    vec3 col = vec3(0);

    // first layer of pattern
    float d = pattern(uv*.5);

    // drawing pattern by collapsing the distance to a defined edge
    col += 1.-smoothstep(0., 0.04, d);            

    // coloring
    col *= palette((abs(uv.x) + abs(uv.y))*.6 + d*15.+off);

    // second layer of pattern
    d = pattern(uv);

    // drawing pattern by collapsing the distance to a defined edge 
    // and inverse (white foreground, black background)
    float pattern = 1.-smoothstep(0., 0.04, d);

    // coloring and overlay result over the first pattern
    col = mix(col, pattern*palette((abs(uv.x) + abs(uv.y))*.6+.3+d*8.+off), pattern);


    // drawing pattern by collapsing the distance to a defined edge
   // col *= 1.-smoothstep(0., 0.01, rug);
    return col;

}

// why not put the raymarcher in a separate function (;
vec3 raymarch(vec3 ro, vec3 rd, float steps) {

    float mat = 0.,
          t   = 0.,
          d   = 0.;
    vec3 p = ro;
    for(float i=.0; i<steps; i++) {

        d = map(p);
        mat = g_mat;  // save global material

        if(abs(d) < 0.0001 || t > 100.) break;

        t += d;
        p += rd*d;
    }

    return vec3(t, mat, t);
}

// from iq code
float softshadow( in vec3 ro, in vec3 rd, in float mint, in float tmax )
{
	float res = 1.0;
    float t = mint;
    for( int i=0; i<1; i++ )
    {
		float h = map( ro + rd*t );
        res = min( res, 8.0*h/t );
        t += h*.25;
        if( h<0.001 || t>tmax ) break;
    }
    return clamp( res, 0., 1. );
}

float calcAO(vec3 p, vec3 n)
{
	float sca = 2.0, occ = 0.0;
    for( int i=0; i<5; i++ ){

        float hr = 0.01 + float(i)*0.5/4.0;        
        float dd = map(n * hr + p);
        occ += (hr - dd)*sca;
        sca *= 0.7;
    }
    return clamp( 1.0 - occ, 0.0, 1.0 );    
}



vec3 getRayDir(vec2 uv, vec3 p, vec3 l, float z) {

    // camera system
    vec3 f = normalize(l - p),  // forward vector
         r = normalize(cross(vec3(0, 1, 0), f)), // right vector
         u = cross(f, r), // up vector
         c = p + f * z, // center of virtual screen
         i = c + uv.x * r + uv.y * u, // intersection with screen
         rd = normalize(i - p);  // ray direction

    return rd;

}

// Shane awesome work below
// Tri-Planar blending function. Based on an old Nvidia tutorial.
vec3 tex3D( sampler2D tex, in vec3 p, in vec3 n ){

    n = max((abs(n) - 0.2)*7., 0.001); // n = max(abs(n), 0.001), etc.
    n /= (n.x + n.y + n.z ); 
	return (texture(tex, p.yz)*n.x + texture(tex, p.zx)*n.y + texture(tex, p.xy)*n.z).xyz;
}



vec3 iriTex( sampler2D tex, in vec3 p, in vec3 n ) {
    vec3 texCol = tex3D(iChannel1, p, n).rgb;
    texCol = texCol;
    mat3 tfm;
    tfm[0] = vec3(texCol.r,0.0,0);
    tfm[1] = vec3(0.0,texCol.b,0);
    tfm[2] = vec3(0,0,1.);    
    n = max((abs(n) - 0.2)*7., 0.001); // n = max(abs(n), 0.001), etc.
    n /= (n.x + n.y + n.z );

    float t = 0.05*tt;
    float s = .5;
    vec2 muvXY = (vec3(p.xy*s,1.0)*tfm).xy - t;
    vec2 muvXZ = (vec3(p.xz*s,1.0)*tfm).xy - t;
    vec2 muvYZ = (vec3(p.yz*s,1.0)*tfm).xy - t;

	return (texture(iChannel2, muvYZ*.1)*n.x + texture(iChannel2, muvXZ*.1)*n.y + texture(iChannel2, muvXY*.1)*n.z).xyz;    
}

// Texture bump mapping. Four tri-planar lookups, or 12 texture lookups in total. I tried to 
// make it as concise as possible. Whether that translates to speed, or not, I couldn't say.
vec3 texBump( sampler2D tx, in vec3 p, in vec3 n, float bf){

    const vec2 e = vec2(0.002, 0);

    // Three gradient vectors rolled into a matrix, constructed with offset greyscale texture values.    
    mat3 m = mat3( tex3D(tx, p - e.xyy, n), tex3D(tx, p - e.yxy, n), tex3D(tx, p - e.yyx, n));

    vec3 coeffs = vec3(0.299*SIN(tt), 0.587, 0.114*SIN(.7*tt));
    vec3 g = coeffs*m; // Converting to greyscale.
    g = (g - dot(tex3D(tx,  p , n), coeffs) )/e.x; g -= n*dot(n, g);

    return normalize( n + g*bf ); // Bumped normal. "bf" - bump factor.

}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
   	vec2 uv = (fragCoord - .5*iResolution.xy)/iResolution.y;

    tt = iTime + 20.;
    float zoom = 9.;
    vec3  lp = vec3(5, 5.-7.*SIN(.2*tt), -15.*sin(0.2*tt+1.)),
          lp2 = vec3(-5., 2, 25);

   // uv = uv.yx;
    vec3 col;

    float m = 4.*sin(.25*tt);
    ro = vec3(m, -3.+0.*SIN(.2*tt), 0);
    vec3 lookat = vec3(m, -3.+5.*SIN(.2*tt), 2.), p;

    vec3 rd = getRayDir(uv, ro, lookat, 1.);

    cam(rd);

    float mat = 0.,
          t   = 0.,
          d   = 0.;


    vec2 e = vec2(0.0035, -0.0035);

    // background color
    vec3 c1 = vec3(0.106,0.255,0.275);
    vec3 c2 = vec3(0.165,0.051,0.286);

    // light color
    vec3 lc1 = vec3(0.843,0.922,0.957);
    vec3 lc2 = vec3(0.957,0.816,0.643);

    float alpha = 0.;


    // currently only one pass
    for(float i = 0.; i < 1.; i++) {
        float steps = i > 0. ? 50. : 300.;
        vec3 rm = raymarch(ro, rd, steps);

        float glow = g_glow;
        mat = rm.y;

        vec3 p = ro + rm.x*rd;

        p = g_p;

        vec3 al = vec3(1);
        if(mat == 1.) {
            al = mandalaTexture(p.xz*.05*mix(1.1, 1., .1*p.y), 0.).rgb;
        }
        if(mat == 2.) {
            float checker = mod(g_fid.x + g_fid.y, 2.);

            al = mix(vec3(1), vec3(0.420,0.702,1.000), checker);
            vec3 tex = mandalaTexture(p.xz*.17, 0.).rgb;
            tex = mandalaTexture(g_fp*.3, (abs(p.x)+abs(p.z))*.2);

            tex = mix(tex, tex*palette((abs(p.x) + abs(p.z))*0.1), .5);

            al = mix(al, 1.2*al*mix(tex, tex.brg, checker), .5);
        }

        vec3 n = normalize( e.xyy*map(p+e.xyy) + e.yyx*map(p+e.yyx) +
                            e.yxy*map(p+e.yxy) + e.xxx*map(p+e.xxx));


        if(mat == 0.) {
            n = texBump(iChannel1,p*1.4,n,.04);
        } else if(mat == 1.) {
            n = texBump(iChannel2,p*.3,n,.06);
        }else if(mat == 2.) {
            n = texBump(iChannel1,p*.8,n,.004);
        }


        if(rm.x < 50.) {


            vec3 l = normalize(lp-p);
            vec3 l2 = normalize(lp2-p);

            float dif = max(dot(n, l), .0);
            float dif2 = max(dot(n, l2), .0);
            float spe = pow(max(dot(reflect(-rd, n), -l), .0),40.);

            float shd=softshadow( p, l, 0.1, 10. );

            float sss = smoothstep(0., 1., map(p + l * .3)) / .4;
            float sss2 = smoothstep(0., 1., map(p + l2 * .3)) / .4;


            vec3 n2 = n;
            n2.xy += noise(p.xy) * .5 - .025;
            n2 = normalize(n2);
            float height = atan(n2.y, n2.x);

            vec3 iri = spectral_zucconi6(height*1.11)*smoothstep(.8, .2, abs(n2.z))-.02;

            col += .5*((dif+.8*sss)*lc1 + (.6*sss2+dif2)*lc2*.8);


            col *= al;

            col += .05*iri;

            float ao = calcAO(p, n);

            col *= mix(col, col*ao, .6);

            rd = reflect(rd, n);

            vec3 refl = texture(iChannel0, rd).rgb;
            refl = mix(refl, refl.rrr, .5);
            refl = invGamma(refl);

            if(mat == 2.) {
                col = mix(col, refl, .11);
                col *= 1.6;
            }
            if(mat == 0.) {
                col = mix(col, refl, .08);
            }
            t = rm.z;
            float fog = 1.-exp(-t*t*0.00005);


            //
            col = mix(col, vec3(0.463,0.294,0.157), fog);
            //if(t > 20.) col *= .2;;

            col = mix(col, col*shd, .5);

        } else {
            col =  mix(vec3(0.082,0.169,0.235), vec3(0), length(uv))*.200; // background

            rd.xz *= rot(-.1*tt);
            col += stars(rd.yz*1.8);
        } 

        col += .05*glow *vec3(0.224,0.941,0.953) ;
        alpha += .05*glow;
    }


    col *= mix(.2, 1., (1.5-pow(dot(uv, uv), .5))); // vignette

    // tone mapping
    col = pow(col*1.2, vec3(1.4))*1.2;

    col = pow(col, vec3(1. / 1.8)) * 1.2;
    col = pow(col, vec3(2.)) * 1.2;
    col = gamma(col); // gamma

    fragColor = vec4(col, alpha);
}
